declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_login();$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT * FROM leads WHERE id=?');$stmt->execute([$id]);$lead=$stmt->fetch();if(!$lead){http_response_code(404);exit('ไม่พบรายการ');}$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$allowed=['new','contacted','confirmed','completed','cancelled'];$status=in_array($_POST['status']??'', $allowed,true)?$_POST['status']:'new';$name=trim((string)$_POST['customer_name']);$phone=trim((string)$_POST['phone']);$email=trim((string)$_POST['email']);$notes=trim((string)$_POST['staff_notes']);$date=(string)$_POST['appointment_date'];$time=(string)$_POST['appointment_time'];if($name===''||!preg_match('/^[0-9+ -]{9,20}$/',$phone)){$success='ข้อมูลไม่ถูกต้อง';}else{$up=db()->prepare('UPDATE leads SET customer_name=?,phone=?,email=?,appointment_date=?,appointment_time=?,status=?,staff_notes=?,updated_by=? WHERE id=?');$up->execute([$name,$phone,$email?:null,$date,$time,$status,$notes?:null,$_SESSION['staff_id'],$id]);$success='บันทึกข้อมูลแล้ว';$stmt->execute([$id]);$lead=$stmt->fetch();}}
$pageTitle='แก้ไขผู้สนใจ';require __DIR__.'/includes/header.php';
?><form class="form-card" method="post"><?=csrf_field()?><?php if($success):?><div class="success"><?=e($success)?></div><?php endif?><div class="form-grid"><label class="field">เลขอ้างอิง<input value="<?=e($lead['reference_no'])?>" disabled></label><label class="field">รุ่นรถ<input value="<?=e($lead['model'])?>" disabled></label><label class="field">ชื่อ-นามสกุล<input name="customer_name" value="<?=e($lead['customer_name'])?>" required></label><label class="field">เบอร์โทร<input name="phone" value="<?=e($lead['phone'])?>" required></label><label class="field">อีเมล<input type="email" name="email" value="<?=e($lead['email'])?>"></label><label class="field">สถานะ<select name="status"><?php foreach(['new'=>'ใหม่','contacted'=>'ติดต่อแล้ว','confirmed'=>'จองแล้ว','completed'=>'ขายแล้ว','cancelled'=>'ยกเลิก'] as $v=>$label):?><option value="<?=$v?>" <?=$lead['status']===$v?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label class="field">วันที่นัดหมาย<input type="date" name="appointment_date" value="<?=e($lead['appointment_date'])?>" required></label><label class="field">เวลา<input type="time" name="appointment_time" value="<?=e(substr($lead['appointment_time'],0,5))?>" required></label></div><label class="field">บันทึกเจ้าหน้าที่<textarea name="staff_notes" rows="5"><?=e($lead['staff_notes'])?></textarea></label><button class="btn">บันทึกการเปลี่ยนแปลง</button> <a class="btn secondary" href="leads.php">กลับ</a></form>
